import { Navigate, useNavigate } from 'react-router-dom'
import { ChangePasswordForm } from '../../auth/ChangePasswordForm'
import { useAuth } from '../../auth/AuthProvider'
import { Button } from '../../primitives/Button'

/**
 * Forced password change for local accounts (issue #113).
 *
 * A local account can hold a password it never chose: the bootstrap admin
 * password generated by the chart, one an admin set when creating the user, or a
 * reset. Grafana's answer is to let such an account authenticate but send it to a
 * change screen instead of the console, which is what this route does — reached
 * from Login, and from RequireAuth for any console route.
 *
 * It renders outside the app shell because there is nothing else to show: the hub
 * gate answers 403 `password_change_required` for every endpoint except
 * /auth/me, /auth/password and /auth/logout. That gate is the enforcement; this
 * screen is the presentation of it, so a user who cannot reach the change screen
 * is not a user who can use a stale password.
 */
export function ForcedPasswordChange() {
  const auth = useAuth()
  const navigate = useNavigate()

  if (!auth.ready) return null
  // Only local accounts have a hub-managed password. OIDC passwords belong to
  // the IdP, and 'none' mode has no accounts at all.
  if (auth.mode !== 'local') return <Navigate to="/dashboard" replace />
  if (!auth.token) return <Navigate to="/login" replace />
  if (!auth.user?.mustChangePassword) return <Navigate to="/dashboard" replace />

  const changed = () => {
    // Clearing the flag locally is presentation only — the hub already cleared
    // its own copy in the same request. Without this the console would render
    // until the next reload.
    auth.setMustChangePassword(false)
    navigate('/dashboard', { replace: true })
  }

  const logOut = () => {
    auth.logout()
    navigate('/login', { replace: true })
  }

  return (
    <div style={{ padding: 32, maxWidth: 480, margin: '0 auto' }}>
      <h1>AInsel</h1>
      <p>
        <b>{auth.user?.username}</b>, your password was issued by an administrator. Choose a
        password of your own to continue.
      </p>
      <ChangePasswordForm onSuccess={changed} />
      <p style={{ marginTop: 24, fontSize: '0.85em' }}>
        Not your account?{' '}
        <Button variant="ghost" size="sm" onClick={logOut}>
          Log out
        </Button>
      </p>
    </div>
  )
}
